+// RF-004: total de una línea con su descuento opcional (0 a 100 %), redondeado al centavo.
+export function calcularTotalLinea(item) {
+  if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
+  if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
+    throw new RangeError("Precio inválido: debe estar en centavos enteros");
+  const descuento = item.descuentoPorcentaje ?? 0;
+  if (typeof descuento !== "number" || !Number.isFinite(descuento) || descuento < 0 || descuento > 100)
+    throw new RangeError("Descuento inválido: debe ser un porcentaje de 0 a 100");
+  const brutoCentavos = item.cantidad * item.precioUnitarioCentavos;
+  return brutoCentavos - Math.round((brutoCentavos * descuento) / 100);
+}
